47: const $=s=>document.querySelector(s);
48: function fresh(seed){return seed.map(x=>({...x,max:x.hp,moves:x.moves.map(m=>({name:m[0],type:m[1],power:m[2]}))}));}
49: function living(team){return team.filter(c=>c.hp>0)}
50: function pct(c){return Math.max(0,c.hp/c.max*100)}
51: function healthColor(p){return p<28?'#ff8069':p<55?'#f2ca65':'#d2f36b'}
52: function bar(c){return `<div class="hp-track"><div class="hp-fill" style="width:${pct(c)}%;background:${healthColor(pct(c))}"></div></div>`}
53: function renderArena(){
54:  $('#playerArena').innerHTML=allies.map(c=>`<div class="beast ${c.hp<=0?'out':''}" id="arena-${c.id}"><div class="creature">${c.emoji}</div><div class="beast-name">${c.name}</div><div class="beast-meta">${c.type.toUpperCase()}</div>${bar(c)}<div class="hp-label">${Math.max(0,c.hp)} / ${c.max} HP</div></div>`).join('');
55:  $('#foeArena').innerHTML=foes.map(c=>`<div class="beast ${c.hp<=0?'out':''}" id="arena-${c.id}"><div class="creature">${c.emoji}</div><div class="beast-name">${c.name}</div><div class="beast-meta">${c.type.toUpperCase()}</div>${bar(c)}<div class="hp-label">${Math.max(0,c.hp)} / ${c.max} HP</div></div>`).join('');
56:  $('#round').textContent=round;$('#allyCount').textContent=`· ${living(allies).length} ACTIVE`;
57: }
58: function targetOptions(c){return living(foes).map(f=>`<option value="${f.id}" ${orders[c.id]?.target===f.id?'selected':''}>${f.name} · ${f.hp} HP</option>`).join('')||'<option>None</option>'}
59: function renderTeam(){
60:  $('#playerTeam').innerHTML=allies.map(c=>{const dead=c.hp<=0,order=orders[c.id]||{move:0,target:living(foes)[0]?.id};if(!dead&&!orders[c.id])orders[c.id]=order;
61:  return `<article class="member ${dead?'fainted':''} ${!dead&&orders[c.id]?.chosen?'active-pick':''}"><div class="member-top"><div class="member-emoji">${c.emoji}</div><div style="min-width:0"><div class="member-name">${c.name}</div><div class="type-tag" style="color:${typeColors[c.type]}">${c.type} · SPD ${c.speed}</div></div></div><div class="member-hp"><span>${dead?'FAINTED':'HP'}</span><span>${Math.max(0,c.hp)} / ${c.max}</span></div>${bar(c)}${dead?'':`<div class="move-controls">${c.moves.map((m,i)=>`<button class="move-btn ${order.move===i?'selected':''}" data-id="${c.id}" data-move="${i}" title="${m.name} · ${m.type} · ${m.power} power">${m.name}</button>`).join('')}</div><select class="target-select" data-target="${c.id}" aria-label="Target for ${c.name}">${targetOptions(c)}</select>`}</article>`}).join('');
62:  $('#playerTeam').querySelectorAll('.move-btn').forEach(b=>b.onclick=()=>{if(busy)return;const id=b.dataset.id;orders[id]={...orders[id],move:+b.dataset.move,chosen:true};renderTeam();renderOrders()});
63:  $('#playerTeam').querySelectorAll('.target-select').forEach(s=>s.onchange=()=>{orders[s.dataset.target]={...orders[s.dataset.target],target:s.value};renderOrders()});
64: }
65: function renderOrders(){let ready=living(allies).filter(c=>orders[c.id]?.chosen).length;$('#orderCount').textContent=`${ready} / ${living(allies).length} READY`;
66:  $('#orders').innerHTML=living(allies).map(c=>{const o=orders[c.id],m=c.moves[o?.move||0],t=foes.find(f=>f.id===o?.target)||living(foes)[0];return `<div class="order"><span><span class="order-icon">${c.emoji}</span>${c.name}</span><small>${o?.chosen?m.name+' → '+(t?.name||'—'):'choose a move'}</small></div>`}).join('')||'<div class="order">No allies left</div>';
67:  $('#resolveBtn').disabled=busy||over||ready!==living(allies).length||ready===0;
68: }
69: function log(text,cls=''){logEntries.unshift(`<p class="${cls}">${text}</p>`);logEntries=logEntries.slice(0,8);$('#log').innerHTML=logEntries.join('')}
70: function effectiveness(moveType,targetType){if(strongAgainst[moveType]===targetType)return 1.5;if(strongAgainst[targetType]===moveType)return .72;return 1}
71: function floatAt(id,text){const el=$(`#arena-${id}`);if(!el)return;const n=document.createElement('div');n.className='float-text';n.textContent=text;el.appendChild(n);setTimeout(()=>n.remove(),950)}
72: function pause(ms){return new Promise(r=>setTimeout(r,ms))}
73: async function resolve(){if(busy||over)return;busy=true;renderOrders();$('#battleStatus').textContent='ROUND IN PROGRESS · WATCH THE WHOLE CREW';
74:  const actions=[];
75:  for(const c of living(allies)){const o=orders[c.id],m=c.moves[o?.move||0];actions.push({user:c,team:allies,targetTeam:foes,move:m,target:o?.target,player:true,speed:c.speed})}
76:  for(const c of living(foes)){const available=c.moves.filter(m=>m.power>=28),m=available[Math.floor(Math.random()*available.length)]||c.moves[0],targets=living(allies);actions.push({user:c,team:foes,targetTeam:allies,move:m,target:targets[Math.floor(Math.random()*targets.length)]?.id,player:false,speed:c.speed})}
77:  actions.sort((a,b)=>b.speed-a.speed||Math.random()-.5);
78:  for(const a of actions){if(a.user.hp<=0)continue;let target=a.targetTeam.find(x=>x.id===a.target&&x.hp>0);if(!target)target=living(a.targetTeam).sort((x,y)=>x.hp-y.hp)[0];if(!target)continue;
79:  const attackEl=$(`#arena-${a.user.id}`),moveType=a.move.type,mult=effectiveness(moveType,target.type),crit=Math.random()<.12,damage=Math.max(8,Math.round((a.move.power*(.82+Math.random()*.36)*mult*(crit?1.45:1))));
80:  attackEl?.classList.add('swing');setTimeout(()=>attackEl?.classList.remove('swing'),480);await pause(170);
81:  target.hp=Math.max(0,target.hp-damage);const targetEl=$(`#arena-${target.id}`);targetEl?.classList.add('hit');setTimeout(()=>targetEl?.classList.remove('hit'),390);floatAt(target.id,`−${damage}${crit?'!':''}`);
82:  let extra=mult>1?' It hit hard!':mult<1?' Not very effective.':'';if(crit)extra+=' Critical hit!';const msg=`<strong>${a.user.name}</strong> used ${a.move.name} on ${target.name} for ${damage}.${extra}`;
83:  log(msg,mult>1?'good':mult<1?'':'');renderArena();await pause(330);
84:  }
85:  round++;orders={};busy=false;renderArena();renderTeam();renderOrders();
86:  if(!living(foes).length||!living(allies).length){over=true;const won=living(foes).length===0;$('#battleStatus').textContent=won?'SQUAD VICTORY':'SQUAD DEFEATED';showEnd(won)}else $('#battleStatus').textContent='YOUR TURN · PLAN ALL MOVES';
87: }
88: function showModal(icon,title,body,button,action,secondary=''){$('#modal').innerHTML=`<div class="modal-icon">${icon}</div><h2>${title}</h2><div>${body}</div><button class="resolve-btn" id="modalAction">${button}</button>${secondary?`<button class="quiet-btn" style="margin-top:9px" id="modalSecondary">${secondary}</button>`:''}`;$('#overlay').classList.remove('hidden');$('#modalAction').onclick=()=>{if(action)action();$('#overlay').classList.add('hidden')};if(secondary)$('#modalSecondary').onclick=()=>$('#overlay').classList.add('hidden')}
89: function showHow(){showModal('⚔️','Every ally. Every round.',`<div class="how-list"><b>01</b> Pick one move for <b>each living ally</b>—they all take a turn.<br><b>02</b> Choose who to target; attacks are aimed at the same time, so a fallen target gets redirected.<br><b>03</b> Faster creatures act first. Match elemental types for extra damage.<br><b>04</b> Defeat the rival squad before they take out yours.</div>`,'Got it',null)}
90: function showEnd(won){showModal(won?'🏆':'💫',won?'Full squad, full victory!':'Your squad needs a breather.',`<p>${won?'Every rival is down. Your whole crew fought as one.':'The rival crew took the round. Tune your targets and try a fresh matchup.'} <b style="color:var(--lime)">Rounds played: ${round-1}</b></p>`,'Play again',()=>resetGame())}
